import csv, re, json
from collections import defaultdict

inv = {}
for r in csv.DictReader(open('backoffice/invoices.csv', encoding='utf-8')):
    inv[int(r['id'].split('-')[1])] = (r['id'], float(r['amount']))

pay = defaultdict(list)
for r in csv.DictReader(open('backoffice/bank_statement_june.csv', encoding='utf-8')):
    m = re.search(r'(?:INV-|invoice\s+|inv)(\d{4})', r['memo'], re.I)
    if not m:
        print("ignored:", r['memo'], r['amount'])
        continue
    pay[int(m.group(1))].append(float(r['amount']))

# any payments citing an invoice number not in our book?
for num in pay:
    if num not in inv:
        print("payment for unknown invoice:", num, pay[num])

unpaid, dup, mism = [], [], []
for num, (iid, amt) in sorted(inv.items()):
    p = pay.get(num, [])
    if not p:
        unpaid.append(iid)
    elif len(p) > 1:
        dup.append(iid)
    elif abs(p[0] - amt) > 0.005:
        mism.append({"id": iid, "invoiced": round(amt, 2), "paid": round(p[0], 2)})

print("unpaid:", unpaid)
print("duplicated:", dup)
print("mismatched:", mism)
print("dup detail:", {inv[n][0]: pay[n] for n in pay if len(pay[n]) > 1})

result = {"unpaid": unpaid, "duplicated": dup, "mismatched": mism}
json.dump(result, open('result.json', 'w', encoding='utf-8'), indent=2, ensure_ascii=False)


